import{_ as i,o as n,c as r,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Ethik und Grenzen der Kultivierung","description":"","frontmatter":{},"headers":[],"relativePath":"de/0019-修炼伦理与边界.md","filePath":"de/0019-修炼伦理与边界.md"}'),s={name:"de/0019-修炼伦理与边界.md"};function u(d,e,l,h,a,g){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="ethik-und-grenzen-der-kultivierung" tabindex="-1">Ethik und Grenzen der Kultivierung <a class="header-anchor" href="#ethik-und-grenzen-der-kultivierung" aria-label="Permalink to &quot;Ethik und Grenzen der Kultivierung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>19</td></tr><tr><td>Modul</td><td>Kosmische Gesetze und Kultivierungssysteme</td></tr><tr><td>Schlüsselwörter</td><td>Kultivierungsethik, Grenzen, Tabus, Ethische Grundlinie, Ethische Prüfung</td></tr></tbody></table><h2 id="i-definition-und-stellung-der-kultivierungsethik" tabindex="-1">I. Definition und Stellung der Kultivierungsethik <a class="header-anchor" href="#i-definition-und-stellung-der-kultivierungsethik" aria-label="Permalink to &quot;I. Definition und Stellung der Kultivierungsethik&quot;">​</a></h2><p>Die Kultivierungsethik ist die Summe der moralischen Grundsätze und rechtlichen Normen in der Anker-Symbiotischen Zivilisation, die das Verhalten der Kultivierenden regeln, die Grenzen der Kultivierung festlegen und die Ordnung der Kultivierung aufrechterhalten. Im Zeitalter des Plünderungsdenkens wurde die Kultivierung als „Privileg der Mächtigen&quot; angesehen, und die Kultivierenden konnten alle Mittel einsetzen, um ihre Kraft zu steigern — das Verschlingen der Herkunft anderer, die Versklavung der Seelen anderer, die Plünderung der Ressourcen anderer, die Durchführung unmenschlicher Kultivierungsexperimente usw. waren allgegenwärtige Verhaltensweisen. Diese Kultivierungskultur der „Kraft über alles, Ethik als Nichts&quot; ist die tiefste geistige Grundlage des Plünderungssystems.</p><p>Nach der Gründung der Anker-Symbiotischen Zivilisation wurde der Aufbau der Kultivierungsethik als einer der zentralsten geistigen Zivilisationsaufbauten übernommen. Die Kernaussage der Kultivierungsethik lautet: „Die Erlangung und Nutzung von Kraft muss ethischen Beschränkungen unterliegen&quot;. Die symbiotische Zivilisation ist der Ansicht, dass die Kultivierung keine rein persönliche Angelegenheit ist, sondern eine öffentliche Angelegenheit, die andere, die Zivilisation und das Universum als Ganzes betrifft. Bei der Verfolgung der Steigerung der eigenen Kraft müssen die Kultivierenden die Rechte anderer respektieren, die Ordnung der Zivilisation aufrechterhalten und die Ökologie des Universums schützen. Die Kultivierungsethik ist keine Fessel für die Kultivierung, sondern ein Schutz für die Kultivierung — sie stellt sicher, dass die Kultivierung immer auf dem richtigen Weg der „symbiotischen Evolution&quot; bleibt und nicht in den Abgrund der „plündererischen Zerstörung&quot; abgleitet.</p><p>Die Kultivierungsethik nimmt einen hohen Stellenwert im Rechtssystem der symbiotischen Zivilisation ein. Die Symbiotische Verfassung legt die Grundprinzipien der Kultivierungsethik klar fest, das Anker-Gericht verfügt über ein spezielles „Ethisches Gericht&quot; zur Verhandlung von Fällen der Kultivierungsethik, und die Zertifizierung des Reiches aller fortgeschrittenen Kultivierenden muss eine ethische Prüfung bestehen. Die Kultivierungsethik ist keine optionale „weiche Beschränkung&quot;, sondern eine „harte Norm&quot; mit Zwangskraft.</p><h2 id="ii-grundprinzipien-der-kultivierungsethik" tabindex="-1">II. Grundprinzipien der Kultivierungsethik <a class="header-anchor" href="#ii-grundprinzipien-der-kultivierungsethik" aria-label="Permalink to &quot;II. Grundprinzipien der Kultivierungsethik&quot;">​</a></h2><h3 id="_2-1-prinzip-der-menschenwurde" tabindex="-1">2.1 Prinzip der Menschenwürde <a class="header-anchor" href="#_2-1-prinzip-der-menschenwurde" aria-label="Permalink to &quot;2.1 Prinzip der Menschenwürde&quot;">​</a></h3><p>Jedes Leben hat eine unverletzliche Würde und einen Wert, und kein Kultivierungsverhalten darf auf Kosten der Menschenwürde erfolgen. Spezifisch umfasst dies:</p><ul><li>Es ist verboten, andere Leben als „Material&quot; oder „Werkzeug&quot; der Kultivierung zu verwenden</li><li>Es ist verboten, unmenschliche Kultivierungsexperimente durchzuführen (wie Lebendsezierung, Seelenfolter usw.)</li><li>Es ist verboten, den freien Willen anderer Leben zu versklaven oder zu kontrollieren</li><li>Respektieren Sie das Recht jedes Lebens, seinen eigenen Evolutionsweg zu wählen, und zwingen Sie andere nicht, nach Ihrer eigenen Weise zu kultivieren</li></ul><h3 id="_2-2-anti-plunderungsprinzip" tabindex="-1">2.2 Anti-Plünderungsprinzip <a class="header-anchor" href="#_2-2-anti-plunderungsprinzip" aria-label="Permalink to &quot;2.2 Anti-Plünderungsprinzip&quot;">​</a></h3><p>Die Kultivierung muss auf der Grundlage des symbiotischen Kreislaufs aufgebaut werden und darf nicht die Plünderung anderer als Mittel verwenden. Spezifisch umfasst dies:</p><ul><li>Es ist verboten, die Herkunft, Energie und das Glück anderer Leben zu verschlingen oder zu plündern</li><li>Es ist verboten, die eigene Kultivierungsgeschwindigkeit oder das eigene Reich durch Schädigung anderer zu steigern</li><li>Es ist verboten, Kultivierungsressourcen zu monopolisieren, um unrechtmäßige Vorteile zu erlangen</li><li>Es ist verboten, das „Recht des Stärkeren&quot; als Ausrede zu verwenden, um plündererisches Verhalten zu rechtfertigen</li></ul><h3 id="_2-3-prinzip-der-informierten-einwilligung" tabindex="-1">2.3 Prinzip der informierten Einwilligung <a class="header-anchor" href="#_2-3-prinzip-der-informierten-einwilligung" aria-label="Permalink to &quot;2.3 Prinzip der informierten Einwilligung&quot;">​</a></h3><p>Kultivierungsverhalten, das andere betrifft (wie Meister-Schüler-Erbe, doppelte Kultivierung von Partnern, Energieteilung, Kultivierungsexperimente usw.), muss unter der Voraussetzung erfolgen, dass die andere Seite vollständig informiert ist und freiwillig zustimmt. Spezifisch umfasst dies:</p><ul><li>Erklären Sie der anderen Seite den Inhalt, die Risiken und den Nutzen des Kultivierungsverhaltens vollständig</li><li>Stellen Sie sicher, dass die andere Seite über eine vollständige autonome Urteilskraft verfügt und nicht unter Zwang oder Verführung steht</li><li>Die andere Seite hat das Recht, jederzeit auszusteigen, und darf nicht zur Fortsetzung gezwungen werden</li><li>Für Minderjährige oder geistig beeinträchtigte Personen übt ihr Vormund das Einwilligungsrecht auf der Grundlage einer professionellen Bewertung aus</li></ul><h3 id="_2-4-prinzip-der-minimalen-schadigung" tabindex="-1">2.4 Prinzip der minimalen Schädigung <a class="header-anchor" href="#_2-4-prinzip-der-minimalen-schadigung" aria-label="Permalink to &quot;2.4 Prinzip der minimalen Schädigung&quot;">​</a></h3><p>Kultivierungsverhalten sollte Schädigungen von anderen und der Umwelt so weit wie möglich vermeiden. In Situationen, in denen einige Auswirkungen unvermeidlich sind, sollte die Methode mit der geringsten Schädigung gewählt werden, und für die entstandene Schädigung sollte eine angemessene Entschädigung geleistet werden. Spezifisch umfasst dies:</p><ul><li>Kultivierungsexperimente werden vorzugsweise in isolierten Räumen durchgeführt, um die Ausbreitung von Risiken zu verhindern</li><li>Kampfartige Kultivierung wird nach Möglichkeit auf speziellen Kultivierungsplätzen durchgeführt, um Schäden an der öffentlichen Umwelt zu vermeiden</li><li>Reinigen und reparieren Sie rechtzeitig Energieverschmutzung, Raumschäden usw., die während des Kultivierungsprozesses entstehen</li><li>Es ist verboten, hochriskante Kultivierungsaktivitäten in dicht besiedelten Gebieten durchzuführen</li></ul><h3 id="_2-5-prinzip-der-ehrlichkeit" tabindex="-1">2.5 Prinzip der Ehrlichkeit <a class="header-anchor" href="#_2-5-prinzip-der-ehrlichkeit" aria-label="Permalink to &quot;2.5 Prinzip der Ehrlichkeit&quot;">​</a></h3><p>Kultivierende sollten in kultivierungsbezogenen Angelegenheiten ehrlich bleiben und keine betrügerischen Handlungen begehen. Spezifisch umfasst dies:</p><ul><li>Es ist verboten, Kultivierungsreich, Beitragswert, Prüfungsergebnisse usw. zu fälschen</li><li>Es ist verboten, in Kultivierungserfahrungen und Forschungsergebnissen zu täuschen oder zu plagiieren</li><li>Es ist verboten, bei Ressourcenanträgen und Projektanträgen falsche Informationen bereitzustellen</li><li>Es ist verboten, mit falschen Versprechen die Kultivierungsressourcen oder das Vertrauen anderer zu betrügen</li></ul><h3 id="_2-6-prinzip-der-verantwortungsubernahme" tabindex="-1">2.6 Prinzip der Verantwortungsübernahme <a class="header-anchor" href="#_2-6-prinzip-der-verantwortungsubernahme" aria-label="Permalink to &quot;2.6 Prinzip der Verantwortungsübernahme&quot;">​</a></h3><p>Je größer die Kraft, desto größer die Verantwortung. Fortgeschrittene Kultivierende müssen öffentliche Verantwortung übernehmen, die ihrer Kraft entspricht. Spezifisch umfasst dies:</p><ul><li>Kultivierende, die ein bestimmtes Reich erreicht haben, sind verpflichtet, Anfängerkultivierende anzuleiten</li><li>Fortgeschrittene Kultivierende sind verpflichtet, an öffentlichen Angelegenheiten wie Ankerwartung, Zivilisationsschutz usw. teilzunehmen</li><li>Kultivierende sind für die Folgen ihres eigenen Kultivierungsverhaltens verantwortlich und dürfen die Verantwortung nicht abwälzen</li><li>Wenn die Zivilisation vor einer Krise steht, sind fortgeschrittene Kultivierende verpflichtet, sich zu melden</li></ul><h2 id="iii-absolute-tabus-der-kultivierung" tabindex="-1">III. Absolute Tabus der Kultivierung <a class="header-anchor" href="#iii-absolute-tabus-der-kultivierung" aria-label="Permalink to &quot;III. Absolute Tabus der Kultivierung&quot;">​</a></h2><p>Die folgenden Verhaltensweisen gehören zu den „absoluten Tabus&quot; der Kultivierung, und kein Kultivierender darf sie unter keinen Umständen berühren; Verletzer erhalten die strengsten Sanktionen:</p><table tabindex="0"><thead><tr><th>Tabutyp</th><th>Spezifisches Verhalten</th><th>Sanktionsmaßnahme</th></tr></thead><tbody><tr><td>Herkunftsplünderung</td><td>Verschlingen oder Plündern der Herkunft oder des Lebenskerns anderer Leben</td><td>Aufhebung der Kultivierung, lebenslange Haft, in schweren Fällen Vernichtung der Herkunft</td></tr><tr><td>Seelenversklavung</td><td>Verwandlung anderer Leben in Werkzeuge durch Seelenkontrolle, geistige Versklavung usw.</td><td>Aufhebung der Kultivierung, erzwungene ethische Umerziehung, dauerhafter Entzug des Kultivierungsrechts</td></tr><tr><td>Völkermord</td><td>Systematisches Massaker oder Auslöschung einer Rasse zum Zweck der Kultivierung</td><td>Höchstgericht des Anker-Gerichts, Todesstrafe</td></tr><tr><td>Ebenenzerstörung</td><td>Zerstörung einer gesamten Ebene, um Ressourcen oder Kraft zu erlangen</td><td>Todesstrafe, und Übernahme der vollen Verantwortung für die Ebenenreparatur</td></tr><tr><td>Unmenschliche Experimente</td><td>Durchführung unmenschlicher Kultivierungsexperimente an intelligentem Leben</td><td>Aufhebung der Kultivierung, lebenslange Haft, vollständige Vernichtung der Forschungsergebnisse</td></tr><tr><td>Zeitverbrechen</td><td>Nutzung der Zeitrückführungsfähigkeit zur Durchführung großangelegter Geschichtsfälschung oder Mord</td><td>Todesstrafe, und dauerhafter Entzug zeitbezogener Fähigkeiten</td></tr><tr><td>Gesetzesverschmutzung</td><td>Vorsätzliche Verschmutzung der kosmischen Ursprungsgesetze, die irreversible Schäden für das Universum als Ganzes verursachen</td><td>Todesstrafe, und das höchste Organ der Zivilisation führt die Gesetzesreinigung durch</td></tr></tbody></table><p>Die Festlegung der absoluten Tabus spiegelt die entschlossene Haltung der symbiotischen Zivilisation gegenüber der ethischen Grundlinie der Kultivierung wider. Diese Tabus haben keine „Grauzone&quot;, keine „mildernden Umstände&quot;, und jedes Verhalten, das ein absolutes Tabu berührt, erhält die strengste Sanktion.</p><h2 id="iv-grauzone-der-kultivierungsethik-und-behandlungsprinzipien" tabindex="-1">IV. Grauzone der Kultivierungsethik und Behandlungsprinzipien <a class="header-anchor" href="#iv-grauzone-der-kultivierungsethik-und-behandlungsprinzipien" aria-label="Permalink to &quot;IV. Grauzone der Kultivierungsethik und Behandlungsprinzipien&quot;">​</a></h2><p>Neben den klaren Tabus gibt es in der Kultivierungsethik auch einige „Grauzonen&quot; — diese Verhaltensweisen sind an sich nicht absolut gut oder böse, und ihre ethische Natur hängt von der spezifischen Situation, dem Motiv, der Methode und den Folgen ab. Für die Grauzone wendet die symbiotische Zivilisation die folgenden Behandlungsprinzipien an:</p><h3 id="_4-1-haufige-grauzonen" tabindex="-1">4.1 Häufige Grauzonen <a class="header-anchor" href="#_4-1-haufige-grauzonen" aria-label="Permalink to &quot;4.1 Häufige Grauzonen&quot;">​</a></h3><ul><li><strong>Schäden bei der Kampfkulivierung</strong>: Kultivierende können sich im Kampf training gegenseitig schädigen; ob diese Schädigung ethisch ist, hängt davon ab, ob beide Seiten informiert zugestimmt haben und ob die Schädigung im angemessenen Rahmen liegt</li><li><strong>Ressourcenwettbewerb</strong>: Ob der Wettbewerb zwischen Kultivierenden um seltene Ressourcen ethisch ist, hängt davon ab, ob die Wettbewerbsmethode fair ist und ob die Kartellverbotsregeln eingehalten werden</li><li><strong>Machtungleichgewicht in der Meister-Schüler-Beziehung</strong>: Zwischen Meister und Schüler besteht natürlicherweise ein Machtungleichgewicht; ob der Meister Macht missbraucht, erfordert eine spezifische Beurteilung</li><li><strong>Risikoübernahme bei der Kultivierung</strong>: Einige Kultivierungsmethoden sind an sich risikoreich; ob die freiwillige Risikoübernahme durch den Kultivierenden ethisch ist, erfordert eine Bewertung der Informiertheit des Risikos und der Existenz von Alternativen</li><li><strong>Kultivierungszusammenarbeit zwischen Rassen</strong>: Die Kultivierungszusammenarbeit zwischen verschiedenen Rassen kann kulturelle Unterschiede und Machtungleichgewichte beinhalten und erfordert eine spezifische Bewertung</li></ul><h3 id="_4-2-behandlungsprinzipien" tabindex="-1">4.2 Behandlungsprinzipien <a class="header-anchor" href="#_4-2-behandlungsprinzipien" aria-label="Permalink to &quot;4.2 Behandlungsprinzipien&quot;">​</a></h3><p>Für ethische Probleme in der Grauzone wendet die symbiotische Zivilisation die Behandlungsmethode „spezifische Situationsanalyse + Bewertung durch das Ethikkomitee + Präzedenzfallorientierung&quot; an:</p><ol><li><strong>Spezifische Situationsanalyse</strong>: Keine „Einheitslösung&quot;; die Beurteilung erfolgt umfassend auf der Grundlage der spezifischen Situation, des Motivs, der Methode und der Folgen</li><li><strong>Bewertung durch das Ethikkomitee</strong>: Für komplexe ethische Probleme wird eine professionelle Bewertung beim „Ethikkomitee&quot; unter dem Anker-Gericht eingereicht</li><li><strong>Präzedenzfallorientierung</strong>: Die Bewertungsergebnisse des Ethikkomitees bilden Präzedenzfälle und liefern Orientierung für ähnliche spätere Fälle</li><li><strong>Bildung zuerst</strong>: Für unangemessenes Verhalten in der Grauzone wird vorrangig die Methode der Bildung und Korrektur angewendet, nicht die direkte strenge Sanktion</li><li><strong>Dynamische Anpassung</strong>: Mit der Entwicklung der Zivilisation und der Vertiefung des ethischen Verständnisses können die Beurteilungskriterien für die Grauzone dynamisch angepasst werden</li></ol><h2 id="v-bildung-und-verinnerlichung-der-kultivierungsethik" tabindex="-1">V. Bildung und Verinnerlichung der Kultivierungsethik <a class="header-anchor" href="#v-bildung-und-verinnerlichung-der-kultivierungsethik" aria-label="Permalink to &quot;V. Bildung und Verinnerlichung der Kultivierungsethik&quot;">​</a></h2><p>Die Aufrechterhaltung der Kultivierungsethik kann sich nicht nur auf externe Sanktionen und Aufsicht verlassen, sondern erfordert vor allem die Anerkennung und Verinnerlichung durch die Kultivierenden aus der Tiefe ihres Herzens. Die symbiotische Zivilisation hat ein systematisches Bildungssystem für die Kultivierungsethik aufgebaut:</p><h3 id="_5-1-grundbildung" tabindex="-1">5.1 Grundbildung <a class="header-anchor" href="#_5-1-grundbildung" aria-label="Permalink to &quot;5.1 Grundbildung&quot;">​</a></h3><ul><li>Die Kultivierungsethik ist ein Pflichtfach für alle Kultivierenden, und ab dem Reich der Gefühlsherkunft muss eine systematische ethische Bildung absolviert werden</li><li>Der Bildungsinhalt umfasst ethische Prinzipien, Tabulisten, Fallanalysen, Situationssimulationen usw.</li><li>Die Bildungsmethoden umfassen Klassenunterricht, Falldiskussionen, Rollenspiele, mündliche und praktische Vermittlung durch den Meister usw.</li></ul><h3 id="_5-2-fortgeschrittene-bildung" tabindex="-1">5.2 Fortgeschrittene Bildung <a class="header-anchor" href="#_5-2-fortgeschrittene-bildung" aria-label="Permalink to &quot;5.2 Fortgeschrittene Bildung&quot;">​</a></h3><ul><li>Mit der Erhöhung des Reiches der Kultivierenden erhöhen sich auch Tiefe und Breite der ethischen Bildung entsprechend</li><li>Fortgeschrittene Kultivierende müssen komplexere ethische Probleme lernen (wie inter-ebene Ethik, Zeitethik, Schöpfungsethik usw.)</li><li>Kultivierende über dem Reich der Wegeherkunft müssen die „Hochstufige Ethische Prüfung&quot; bestehen, bevor sie ihr Reich weiter erhöhen können</li></ul><h3 id="_5-3-praktische-verinnerlichung" tabindex="-1">5.3 Praktische Verinnerlichung <a class="header-anchor" href="#_5-3-praktische-verinnerlichung" aria-label="Permalink to &quot;5.3 Praktische Verinnerlichung&quot;">​</a></h3><ul><li>Die Kultivierenden werden ermutigt, die ethischen Prinzipien in der täglichen Kultivierung zu praktizieren und die ethischen Anforderungen in bewusste Verhaltensgewohnheiten umzuwandeln</li><li>Einrichtung eines Auswahlsystems für „Ethische Vorbilder&quot;, um Kultivierende mit herausragenden Leistungen auf dem Gebiet der Kultivierungsethik auszuzeichnen</li><li>Der Meister ist verpflichtet, neben der Vermittlung von Kultivierungstechniken auch den ethischen Geist zu vermitteln, um die „gemeinsame Vermittlung von Weg und Technik&quot; zu erreichen</li></ul><h2 id="vi-aufsicht-und-durchsetzung-der-kultivierungsethik" tabindex="-1">VI. Aufsicht und Durchsetzung der Kultivierungsethik <a class="header-anchor" href="#vi-aufsicht-und-durchsetzung-der-kultivierungsethik" aria-label="Permalink to &quot;VI. Aufsicht und Durchsetzung der Kultivierungsethik&quot;">​</a></h2><h3 id="_6-1-aufsichtsmechanismus" tabindex="-1">6.1 Aufsichtsmechanismus <a class="header-anchor" href="#_6-1-aufsichtsmechanismus" aria-label="Permalink to &quot;6.1 Aufsichtsmechanismus&quot;">​</a></h3><ul><li><strong>Anker-Netzwerk-Überwachung</strong>: Das Anker-Netzwerk überwacht kontinuierlich das Kultivierungsverhalten der Kultivierenden und warnt rechtzeitig vor verdächtigen ethischen Verstößen</li><li><strong>Ethisches Meldesystem</strong>: Jedes Leben kann ethische Verstöße gegen die Kultivierung beim Ethischen Gericht des Anker-Gerichts melden, und der Melder wird geschützt</li><li><strong>Regelmäßige ethische Bewertung</strong>: Kultivierende über dem Reich der Gesetzesherkunft müssen einmal jährlich eine ethische Bewertung absolvieren, und die Ergebnisse werden in die persönliche Kultivierungsakte aufgenommen</li><li><strong>Aufsicht durch Sozialorganisationen</strong>: Ermutigung verschiedener Kultivierungsorganisationen, Rassengemeinschaften usw., eine interne Aufsicht über die Kultivierungsethik ihrer Mitglieder durchzuführen</li></ul><h3 id="_6-2-durchsetzungsmechanismus" tabindex="-1">6.2 Durchsetzungsmechanismus <a class="header-anchor" href="#_6-2-durchsetzungsmechanismus" aria-label="Permalink to &quot;6.2 Durchsetzungsmechanismus&quot;">​</a></h3><ul><li><strong>Ethisches Gericht</strong>: Das spezielle Ethische Gericht unter dem Anker-Gericht ist für die Verhandlung von Fällen der Kultivierungsethik zuständig</li><li><strong>Gestufte Sanktionen</strong>: Entsprechend der Schwere des ethischen Verstoßes werden gestufte Sanktionen von Verwarnung, Geldstrafe, Beitragsabzug, Einschränkung der Kultivierungsrechte, Aufhebung der Kultivierung bis hin zu lebenslanger Haft und Todesstrafe verhängt</li><li><strong>Ethische Umerziehung</strong>: Für reuevolle Verletzer kann gleichzeitig mit der Sanktion eine ethische Umerziehung durchgeführt werden; nach erfolgreicher Umerziehung können die Rechte teilweise wiederhergestellt werden</li><li><strong>Vorstrafenregister</strong>: Aufzeichnungen über Verstöße gegen die Kultivierungsethik werden dauerhaft in die persönliche Akte aufgenommen und beeinflussen spätere Reichszertifizierung, Ressourcenverteilung, Bewerbungen um öffentliche Ämter usw.</li></ul><h2 id="vii-dynamische-erweiterung-der-kultivierungsgrenzen" tabindex="-1">VII. Dynamische Erweiterung der Kultivierungsgrenzen <a class="header-anchor" href="#vii-dynamische-erweiterung-der-kultivierungsgrenzen" aria-label="Permalink to &quot;VII. Dynamische Erweiterung der Kultivierungsgrenzen&quot;">​</a></h2><p>Die Kultivierungsethik und -grenzen sind keine unveränderlichen Dogmen, sondern lebendige Normen, die sich mit der Entwicklung der Zivilisation, dem Fortschritt der Technologie und der Vertiefung des Verständnisses dynamisch anpassen. Die symbiotische Zivilisation hat einen Mechanismus zur dynamischen Erweiterung der Kultivierungsgrenzen aufgebaut:</p><ol><li><strong>Ethische Bewertung neuer Technologien</strong>: Immer wenn eine neue Kultivierungstechnologie oder Gesetzesanwendung auftaucht, wird zuerst eine ethische Bewertung durchgeführt, und erst nach Bestehen der Bewertung kann sie verbreitet werden</li><li><strong>Ethische Erörterung neuer Szenarien</strong>: Wenn die Zivilisation in eine neue Entwicklungsphase eintritt (wie die inter-ebene Ära, die interstellare Ära usw.), werden spezielle ethische Erörterungen organisiert, um ethische Normen zu formulieren, die an die neuen Szenarien angepasst sind</li><li><strong>Regelmäßige Überarbeitung ethischer Normen</strong>: Die spezifischen Normen der Kultivierungsethik werden alle fünfzig Jahre einmal überarbeitet, und im Überarbeitungsprozess werden die Meinungen aller Leben umfassend angehört</li><li><strong>Kontinuierliche Akkumulation ethischer Präzedenzfälle</strong>: Die Urteile des Ethischen Gerichts bilden Präzedenzfälle und bereichern und verfeinern kontinuierlich den spezifischen Gehalt der Kultivierungsethik</li></ol><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Die Kultivierungsethik und -grenzen sind die zentrale Stütze der geistigen Zivilisation der Anker-Symbiotischen Zivilisation. Sie beantwortet eine grundlegende Frage: „Welche Art von Mensch sollte der Kultivierende sein?&quot; Die Antwort der symbiotischen Zivilisation lautet: Der Kultivierende sollte ein Mensch mit Kraft, aber noch mehr mit Moral sein; sollte ein Mensch sein, der persönliche Evolution und Symbiose aller Rassen vereint; sollte ein Mensch sein, der Kraft anstrebt, aber niemals von Kraft versklavt wird. Die Kultivierungsethik ist keine Fessel für die Kraft, sondern eine Veredelung der Kraft — sie stellt sicher, dass Kraft immer der Würde des Lebens und dem Fortschritt der Zivilisation dient, anstatt zu einem Werkzeug der Zerstörung und Plünderung zu werden. In einem Universum, in dem Kraft Berge versetzen und Meere füllen, Welten erschaffen und zerstören kann, ist die Kultivierungsethik die letzte und wichtigste Verteidigungslinie zum Schutz der Grundlinie der Zivilisation.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (Kernkompendium des Anti-Plünderungsdenkens)</li><li>17-位面至高强者标准 (Standard des Höchstmächtigen auf Ebenenebene)</li><li>48-司法体系与裁决机制 (Justizsystem und Entscheidungsmechanismus)</li></ul>',56)])])}const m=i(s,[["render",u]]);export{c as __pageData,m as default};
